// Types + licence policy for seed photos sourced from Wikimedia Commons.
// The data itself lives in photos.json (generated by `pnpm photos:fetch`, reviewed, committed).
import { readFileSync } from "node:fs";
import { join } from "node:path";

export interface PhotoEntry {
  /** Commons file title, e.g. "File:Sigiriya.jpg". */
  file: string;
  /** Commons description page (linked from the credit line). */
  sourceUrl: string;
  /** ≤1600px rendition the fetch script downloads. */
  thumbUrl: string;
  author: string;
  license: string;
  licenseUrl: string | null;
  wikidata: string | null;
  wikidataCoords: { lat: number; lng: number } | null;
  /** Distance between our seed coordinates and Wikidata's, in metres. */
  coordsDeltaM: number | null;
  via: "wikidata-p18" | "wikipedia-lead" | "commons-category" | "commons-search";
  /** Set during manual review when a photo doesn't actually show the place. */
  rejected?: string;
}

/**
 * Free licences only: CC0, CC BY, CC BY-SA, public domain, Free Art License, plain "Attribution".
 * Rejects NC/ND, fair use, GFDL-only (needs the full licence text alongside) and anything unlabelled.
 */
export function isFreeLicense(short: string): boolean {
  const s = short.toLowerCase().trim();
  if (!s || /\bnc\b|non-?commercial|\bnd\b|no-?deriv|fair use|copyrighted/.test(s)) return false;
  return /^(cc0|cc[ -]by(-sa)?([ -]?\d.*)?$|public domain|pd\b|pd-|fal\b|free art licen[cs]e|attribution$)/.test(
    s,
  );
}

export function loadPhotos(): Record<string, PhotoEntry | null> {
  try {
    return JSON.parse(readFileSync(join(process.cwd(), "src/server/seed/photos.json"), "utf8"));
  } catch {
    return {};
  }
}
